@php($variationRows = old('variations', $draftValues['variations'] ?? (isset($product) ? $product->variations->where('is_active', true)->values()->map(fn ($variant) => $variant->only(['id','type','value','sku','image_path','price_adjustment','stock']))->all() : [])))
<section class="web-variation-editor" data-variation-editor>
<h2>Product variations</h2><p>Set the full selling price and stock for every combination. Cards show the price range and combined active stock. Removing a row retires it while preserving order history.</p>
@php($optionsEnabled = old('variations_enabled', $draftValues['variations_enabled'] ?? (isset($product) ? $product->usesVariations() : count($variationRows) > 0)))
<fieldset id="variation-options" class="border-0 p-0 min-w-0" data-variation-options @if(!$optionsEnabled) hidden disabled @endif><legend class="sr-only">Variation prices and stock</legend><input type="hidden" name="variations_present" value="1">
<fieldset class="web-form"><legend>Generate combinations (optional)</legend><label>First attribute<input type="text" data-attribute-name placeholder="Size" maxlength="20"></label><label>Options, separated by commas<input type="text" data-attribute-options placeholder="Small, Medium, Large"></label><label>Second attribute<input type="text" data-attribute-name placeholder="Color" maxlength="20"></label><label>Options, separated by commas<input type="text" data-attribute-options placeholder="Black, White"></label><button type="button" class="dash-btn-sm" data-generate-variations>Generate combinations</button></fieldset>
<div class="dash-table-wrapper"><table class="dash-table"><thead><tr><th>Attribute(s)</th><th>Combination</th><th>SKU (optional)</th><th>Price (PHP)</th><th>Stock</th><th>Image (optional, 2 MB)</th><th>Action</th></tr></thead><tbody data-variation-rows>
@foreach($variationRows as $index => $row)<tr data-variation-row>
<td>@if(!empty($row['id']))<input type="hidden" name="variations[{{ $index }}][id]" value="{{ $row['id'] }}">@endif<input aria-label="Variation attributes" name="variations[{{ $index }}][type]" value="{{ $row['type'] ?? '' }}" maxlength="50" required data-variation-type></td>
<td><input aria-label="Variation combination" name="variations[{{ $index }}][value]" value="{{ $row['value'] ?? '' }}" maxlength="50" required data-variation-value></td>
<td><input aria-label="Variation SKU" name="variations[{{ $index }}][sku]" value="{{ $row['sku'] ?? '' }}" maxlength="64"></td>
<td><input aria-label="Variation price" min="0.01" max="99999999.99" data-variation-price type="number" step="0.01" name="variations[{{ $index }}][price]" value="{{ $row['price'] ?? ((float) old('price', $draftValues['price'] ?? ($product->price ?? 0)) + (float) ($row['price_adjustment'] ?? 0)) }}" required></td>
<td><input aria-label="Variation stock" type="number" min="0" max="1000000" name="variations[{{ $index }}][stock]" value="{{ $row['stock'] ?? 0 }}" required data-variation-stock></td>
<td>@if(!empty($row['image_path']))<img class="web-variation-preview" src="{{ asset('storage/'.$row['image_path']) }}" alt="Current variation image">@endif<input aria-label="Replace variation image" type="file" name="variations[{{ $index }}][image]" accept="image/jpeg,image/png,image/webp"></td><td><button class="dash-btn-sm" type="button" data-remove-variation>Remove</button></td></tr>@endforeach
</tbody></table></div><div class="web-actions web-section"><button class="dash-btn-sm" type="button" data-add-variation>Add variation row</button><p role="status" data-variation-feedback>Up to 100 combinations. Add at least one variation when enabled.</p></div>
<template data-variation-template><tr data-variation-row><td><input aria-label="Variation attributes" name="variations[__INDEX__][type]" maxlength="50" required data-variation-type></td><td><input aria-label="Variation combination" name="variations[__INDEX__][value]" maxlength="50" required data-variation-value></td><td><input aria-label="Variation SKU" name="variations[__INDEX__][sku]" maxlength="64"></td><td><input aria-label="Variation price" min="0.01" max="99999999.99" data-variation-price type="number" step="0.01" name="variations[__INDEX__][price]" value="" required></td><td><input aria-label="Variation stock" type="number" min="0" max="1000000" name="variations[__INDEX__][stock]" value="0" required data-variation-stock></td><td><input aria-label="Variation image" type="file" name="variations[__INDEX__][image]" accept="image/jpeg,image/png,image/webp"></td><td><button class="dash-btn-sm" type="button" data-remove-variation>Remove</button></td></tr></template>
<p role="status" data-variation-summary></p></fieldset></section>
